def solution(n):
    if n == 0:
        return []
    digits = str(n)
    result = []
    current_group = []
    current_type = None
    for digit in digits:
        if current_type is None:
            current_type = int(digit) % 2
            current_group.append(digit)
        elif int(digit) % 2 == current_type:
            current_group.append(digit)
        else:
            result.append(int(''.join(current_group)))
            current_type = int(digit) % 2
            current_group = [digit]
    if current_group:
        result.append(int(''.join(current_group)))
    return result
